// Fetch each RSS feed and capture errors per source
const sources = $input.all()[0].json || [];
const results = [];

for (const source of sources) {
  try {
    const res = await $httpRequest({
      method: 'GET',
      url: source.url,
      responseFormat: 'text',
      timeout: 20000
    });
    results.push({
      json: {
        source_id: source.id,
        source_name: source.name,
        source_language: source.language || 'en',
        category_id: source.category_id,
        xml: String(res),
        fetch_error: null
      }
    });
  } catch (err) {
    results.push({
      json: {
        source_id: source.id,
        source_name: source.name,
        fetch_error: err.message || 'Failed to fetch RSS'
      }
    });
  }
}
return results;

// Parse RSS XML and generate articles
const Parser = require('rss-parser');
const parser = new Parser();
const outputs = [];

for (const item of $input.all()) {
  const feed = item.json;
  if (feed.fetch_error) {
    outputs.push({
      json: {
        source_id: feed.source_id,
        step: 'fetch',
        status: 'error',
        message: feed.fetch_error
      }
    });
    continue;
  }

  try {
    const parsed = await parser.parseString(feed.xml);
    for (const article of parsed.items.slice(0, 20)) {
      const url = (article.link || article.guid || '').split('#')[0].trim();
      if (!url) continue;
      const cleanUrl = url.split('?')[0];
      const title = (article.title || '').trim();
      const contentHash = Buffer.from(title.toLowerCase() + '|' + cleanUrl).toString('base64');
      outputs.push({
        json: {
          source_id: feed.source_id,
          source_url: url,
          canonical_url: cleanUrl,
          content_hash: contentHash,
          source_type: 'news',
          original_language: feed.source_language,
          category_id: feed.category_id,
          title: title,
          published_date: article.isoDate || article.pubDate || null,
          author: article.author || article.creator || null,
          status: 'pending',
          parse_error: null
        }
      });
    }
  } catch (err) {
    outputs.push({
      json: {
        source_id: feed.source_id,
        step: 'parse',
        status: 'error',
        message: err.message || 'Failed to parse RSS'
      }
    });
  }
}
return outputs;

// Route parse errors to log; pass new articles forward
const items = $input.all();
const errors = items.filter(i => i.json.step && i.json.status === 'error');
const articles = items.filter(i => !i.json.step && !i.json.parse_error);

const output = [
  ...articles.map(i => ({ json: i.json })),
  ...errors.map(i => ({ json: i.json }))
];
return output;

// Keep only non-duplicate articles; log duplicates and errors
const duplicate = $input.all();
const item = $input.first().json;

if (item.step && item.status === 'error') {
  return [{ json: item }]; // pass through to log
}

if (duplicate.length === 0 || !duplicate[0].json.id) {
  return [{ json: item }];
}

return [{ json: { source_id: item.source_id, step: 'dedupe', status: 'skipped', message: 'Duplicate: ' + item.source_url } }];

const item = $input.first().json;
if (item.id) {
  return [{ json: { article_id: item.id, source_id: item.source_id, step: 'fetch', status: 'success', message: 'Article ingested from RSS' } }];
}
if (item.step) {
  return [{ json: item }]; // error/skip log
}
return [];
